/**
 * Insurer customer-care and claims contacts, keyed by `insurerSlug()`.
 *
 * Every value was read on the insurer's own website (the `source` page) on
 * `checkedOn`. Left out on purpose, so nothing here is a guess:
 *   - navi-general: navi.com shows only a Navi-wide number, no insurance line
 *   - niva-bupa: the only number found was in a 2024 blog post; the customer-service page lists none
 *   - lic (claims lines): the listed "claims" number is a health TPA, not for death claims
 *   - icici-prudential-life (claims lines): two different claims numbers on different pages
 *   - royal-sundaram (claims lines): claim-line labels could not be tied to numbers reliably
 *   - reliance-general WhatsApp and claims email: they differ by page / belong to a travel partner
 *
 * To update: re-check the number on the insurer's own site, then edit the entry
 * and its `source` and `checkedOn`.
 */
export interface InsurerContact {
  /** Customer-care lines, as printed. 1800 = toll-free; 1860 = shared cost. */
  phones: string[];
  claimsPhones: Array<{ label: string; numbers: string[] }>;
  whatsapp: string | null;
  email: string | null;
  claimsEmail: string | null;
  claimUrl: string | null;
  grievanceUrl: string | null;
  grievanceEmail: string | null;
  /** The insurer page these were read from. */
  source: string;
  checkedOn: string;
}

